function hevUnit(N, P){
  const z = {N:0, teach:0, sup:0, oth:0, cost:0, m2:0};
  if (N <= 0.5) return z;
  const EMPm = 12*EMP, classes = N/P.hevClass;
  const teach = classes*P.hevLoad*(1+P.extra/100)/P.contact*(1+P.addOn/100);
  const asst = classes*P.hevAsst, spec = N*P.hevSup/P.supContact;
  const lead = N/150, adm = N/300, m2 = N*P.hevM2;
  const bldStaff = m2/P.m2Clean + m2/2500 + N/P.mealsPerCook;
  const cost = teach*P.tSal*EMPm + (asst*P.abiSal + spec*P.supSal + lead*P.dirSal*0.85 + adm*P.adminSal + bldStaff*P.techSal)*EMPm
    + m2*P.opM2 + N*(P.perMat + P.perIT + P.perOther + DAYS*P.mealIng + P.hevTrans);
  return {N, teach, sup: asst+spec, oth: lead+adm+bldStaff, cost, m2};
}
