function update(){
  const R=compute(baseP());
  const RT=compute(techP(),{runs:0});
  cards(R); viewOma(R); viewKulud(R); viewOpetajad(R); viewRuumid(R); viewVork(R); viewGym(R); viewTech(R.map(x=>x), RT); viewParis(R); viewSoovitus(R, RT);
}
const PER = o => (o.cost - (o.voc||0))/Math.max(1,o.N);
/* ===== PROGNOOSI VAADE ===== */
