// prognoos (Olukord, Prognoos 2040) hõlmab ka HEV-erikoole; täiskasvanute gümnaasiumid on ilma õpilasteta
const SCHOOLS_FC = schoolsFromRows(SCHOOL_ROWS).map(t=>/Täiskasvanute/.test(t.name) ? {...t, n:t.n.map(()=>0), adult:true} : t);
const SCHOOLS = schoolsFromRows(SCHOOL_ROWS).map(t=>/Täiskasvanute/.test(t.name) ? {...t, n:t.n.map(()=>0), adult:true} : HEV_SCHOOLS.has(t.name) ? {...t, n:t.n.map(()=>0), hev:true} : t);
let FC0 = null, FC = null, fcYear = 2040, fcMetric = 'N', fcMode = 'abs', fcSel = null, fcShowSch = true, fcTimer = null, fcPlay = null, fcDirty = true;
const MET = {
  schools:{l:'Koolid', f:v=>nf(v), unit:'kooli'},
  N:{l:'Õpilased', f:v=>nf(v), unit:'õpilast'},
  teach:{l:'Õpetajad', f:v=>nf(v), unit:'ametikohta'},
  sup:{l:'Tugitöötajad', f:v=>nf(v), unit:'ametikohta'},
  cost:{l:'Hariduskulud', f:v=>nf(v/1e6,1)+' mln €', unit:''},
  per:{l:'Kulu õpilase kohta', f:v=>eur(v), unit:''},
  neet:{l:'Noored, kes ei õpi', f:v=>nf(v), unit:'noort'}};
const MAPC = ['Harju','Hiiu','Ida-Viru','Jõgeva','Järva','Lääne','Lääne-Viru','Põlva','Pärnu','Rapla','Saare','Tartu','Valga','Viljandi','Võru'];
function cval(c, yi, m){
  const parts = c==='Harju' ? ['Harju','Tallinn'] : [c];
  const a = {N:0, teach:0, sup:0, oth:0, cost:0, op:0, oneoff:0, fixArea:0, lag:0, m2:0, schools:0, closed:0, alg:0, hevN:0, neet:0, neetBack:0, voc:0, chose:0, belowN:0, toVoc:0, dormN:0};
  parts.forEach(p => { const x = FC.county[p][yi]; Object.keys(a).forEach(k => a[k]+=x[k]); });
  if (m==='per') return PER(a);
  return m ? a[m] : a;
}
function tval(yi, m){ const t = FC.total[yi]; return m==='per' ? PER(t) : t[m]; }
function fcCompute(){ FC_DEC = null;
  const st = document.getElementById('fcStatus'); if (st) st.textContent = 'Arvutan 456 kooli × 15 aastat…';
  setTimeout(()=>{ const t0 = performance.now(); const Q = {...baseP()}; FC = forecast(SCHOOLS, IDX, Q); FC0 = Q.netPol>0 ? forecast(SCHOOLS, IDX, {...Q, netPol:0}) : FC; fcDirty = false;
    if (st) st.textContent = `Arvutatud ${nf((performance.now()-t0)/1000,1)} s · ${SCHOOLS.length} kooli`; fcRender(); }, 30);
}
function fcSchedule(){ fcDirty = true; const vis = !document.getElementById('p-prognoos').hidden; if (!vis) return; clearTimeout(fcTimer); fcTimer = setTimeout(fcCompute, 500); }
function colorScale(vals, mode){
  if (mode==='chg'){
    const bins=[-60,-45,-30,-15,0,15,30]; const cols=['--d1','--d2','--d3','--d4','--d5','--d6','--d7','--d8'];
    return {f:v=>`var(${cols[bins.findIndex(b=>v<b)===-1?7:bins.findIndex(b=>v<b)]})`, legend: cols.map((c,i)=>[c, i===0?`< ${bins[0]}%`: i===7?`> ${bins[6]}%`:`${bins[i-1]}…${bins[i]}%`])};
  }
  const s=[...vals].sort((a,b)=>a-b), q=[.2,.4,.6,.8].map(p=>s[Math.floor(p*(s.length-1))]); const cols=['--q1','--q2','--q3','--q4','--q5'];
  return {f:v=>`var(${cols[q.findIndex(b=>v<b)===-1?4:q.findIndex(b=>v<b)]})`, legend: cols.map((c,i)=>[c, i===0?`< ${MET[fcMetric].f(q[0])}`: i===4?`> ${MET[fcMetric].f(q[3])}`:`${MET[fcMetric].f(q[i-1])} – ${MET[fcMetric].f(q[i])}`])};
}
const SG = v => v>0.0001 ? '+' : (v<-0.0001 ? '−' : '±');
/* muutus tükkides, sulgudes protsent: −1 234 (−12%) */
function dch(a, b, f, cls){ const d = a-b, p = b ? (a/b-1)*100 : 0; return `<span class="chg ${cls||(d>0.0001?'up':'dn')}">${SG(d)}${f(Math.abs(d))} (${SG(p)}${nf(Math.abs(p))}%)</span>`; }
const MSHORT = {schools:v=>nf(v), N:v=>nf(v), teach:v=>nf(v), sup:v=>nf(v), cost:v=>nf(v/1e6,v<1e7?1:0)+' mln', per:v=>nf(v/1000,1)+' tuh', neet:v=>nf(v)};
function fcMap(){
  const yi = FC.years.indexOf(fcYear);
  const v = c => fcMode==='chg' ? (cval(c,yi,fcMetric)/cval(c,0,fcMetric)-1)*100 : cval(c,yi,fcMetric);
  const dv = c => cval(c,yi,fcMetric) - cval(c,0,fcMetric);
  const vals = MAPC.map(v), sc = colorScale(vals, fcMode);
  let s = `<svg class="chart fcmap" viewBox="-6 -6 ${MAP.w+12} ${MAP.h+12}" role="img" aria-label="Eesti maakonnad: ${MET[fcMetric].l} ${fcYear}"><rect class="bg" x="-6" y="-6" width="${MAP.w+12}" height="${MAP.h+12}"><title>Klõpsa tühjal alal, et näha Eestit kokku</title></rect>`;
  MAPC.forEach((c,i) => { s += `<path d="${MAP.c[c].d}" fill="${sc.f(vals[i])}" stroke="var(--surface)" stroke-width="1.2" class="cty${fcSel===c?' sel':''}" data-c="${c}"><title>${c}maa ${fcYear}: ${MET[fcMetric].f(cval(c,yi,fcMetric))} · muutus vs 2026 ${SG(dv(c))}${MET[fcMetric].f(Math.abs(dv(c)))} (${SG(dv(c))}${nf(Math.abs(cval(c,yi,fcMetric)/cval(c,0,fcMetric)-1)*100)}%)</title></path>`; });
  if (fcShowSch){
    SCHOOLS.forEach((sch,i) => { const n = FC.sch[i].N[yi]; const r = Math.max(1.2, Math.sqrt(Math.max(n,1))/7);
      s += `<circle cx="${sch.x}" cy="${sch.y}" r="${FC.open[i]||n>0? r : 1.6}" class="sch${n>0?(FC.alg[i]?' alg':''):' closed'}"><title>${sch.name} (${sch.county}) · ${fcYear}: ${n>0? (FC.alg[i]?'algkool, ':'')+nf(n)+' õpilast, '+nf(FC.sch[i].teach[yi],1)+' õpetaja kohta, '+eur(FC.sch[i].cost[yi]/n)+' õpilase kohta' : 'liidetud'}</title></circle>`; });
  }
  MAPC.forEach((c,i) => { const p = MAP.c[c]; const d = dv(c); const lbl = fcMode==='chg' ? SG(d)+MSHORT[fcMetric](Math.abs(d)) : MSHORT[fcMetric](vals[i]);
    const pl = fcMode==='chg' ? `<text x="${p.cx}" y="${p.cy+21}" text-anchor="middle" class="ln">(${SG(vals[i])}${nf(Math.abs(vals[i]))}%)</text>` : '';
    s += `<g class="lbl" pointer-events="none"><text x="${p.cx}" y="${p.cy-3}" text-anchor="middle" class="ln">${c}</text><text x="${p.cx}" y="${p.cy+10}" text-anchor="middle" class="lv">${lbl}</text>${pl}</g>`; });
  s += '</svg>';
  return {svg:s, legend: sc.legend};
}
function lineChart(series, title, fmt){
  const W=420,H=170,l=64,r=14,t=12,b=24, ys=FC.years;
  const all=series.flatMap(s=>s.v); const max=Math.max(...all)*1.08, min=Math.min(0, ...all);
  const X=i=>l+i/(ys.length-1)*(W-l-r), Y=v=>t+(1-(v-min)/(max-min))*(H-t-b);
  let s=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${title}">`;
  for(let k=0;k<=4;k++){ const v=min+(max-min)*k/4; s+=`<line x1="${l}" x2="${W-r}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--soft)"/><text x="${l-6}" y="${Y(v)+4}" text-anchor="end">${fmt(v)}</text>`; }
  [0,4,9,14].forEach(i=> s+=`<text x="${X(i)}" y="${H-6}" text-anchor="middle">${ys[i]}</text>`);
  const yi=ys.indexOf(fcYear); s+=`<line x1="${X(yi)}" x2="${X(yi)}" y1="${t}" y2="${H-b}" stroke="var(--muted)" stroke-dasharray="3 3"/>`;
  series.forEach(se=>{ s+=`<path d="${se.v.map((v,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)).join('')}" fill="none" stroke="${se.c}" stroke-width="2.2"/><circle cx="${X(yi)}" cy="${Y(se.v[yi])}" r="3.5" fill="${se.c}"/>`; });
  return s+'</svg>';
}
function spark(vals, col){
  const W=200,H=26,ys=FC.years, yi=ys.indexOf(fcYear); const mx=Math.max(...vals), mn=Math.min(...vals), rg=(mx-mn)||1;
  const X=i=>2+i/(ys.length-1)*(W-4), Y=v=>H-3-(v-mn)/rg*(H-6);
  return `<svg class="sp" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><path d="${vals.map((v,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)).join('')}" fill="none" stroke="${col}" stroke-width="1.6" vector-effect="non-scaling-stroke"/><line x1="${X(yi)}" x2="${X(yi)}" y1="0" y2="${H}" stroke="var(--muted)" stroke-dasharray="2 2" vector-effect="non-scaling-stroke"/></svg>`;
}
