let FC_DEC = null;
function fcDecomp(){
  const box = document.getElementById('fcDecomp'); box.innerHTML = '<p class="small">Arvutan 7 varianti…</p>';
  const steps = [['Väiksemad koolid ja klassid (demograafia, hinnad 2026)', null], ['Hoonete pind ei vähene', 'area'], ['Personal väheneb aeglasemalt kui õpilased', 'lag'], ['Tugivajaduse kasv', 'sup'], ['Hoonete ülalpidamise hinnatõus', 'util'], ['Palkade kasv', 'wage'], ['Koolide sulgemise ühekordsed kulud', 'close']];
  const Q = {...baseP(), nominal:0};
  const offs = {area:1, lag:1, sup:1, util:1, wage:1, close:1};
  const res = []; let k = 0;
  const per = F => [PER(F.total[0]), PER(F.total[14])];
  const next = () => {
    if (k < steps.length){ if (steps[k][1]) delete offs[steps[k][1]]; const F = forecast(SCHOOLS, IDX, Q, {off:{...offs}}); res.push(per(F)); k++; setTimeout(next, 10); return; }
    const p0 = res[0][0]; let prev = p0; const rows = []; const max = res[res.length-1][1];
    steps.forEach((s,i) => { const v = res[i][1]; rows.push([s[0], v - prev, v]); prev = v; });
    const W = 100/max;
    FC_DEC = `<div class="tbl-wrap" style="border:0; margin-top:8px"><table><thead><tr><th>Põhjus</th><th>€/õpilane</th><th>kumulatiivne</th></tr></thead><tbody>
      <tr><td>2026 (lähtetase)</td><td></td><td>${eur(p0)}</td></tr>
      ${rows.map(r=>`<tr><td>${r[0]}<div class="bar" style="height:6px;background:var(--soft);border-radius:3px;margin-top:3px"><i style="display:block;height:100%;margin-left:${(r[2]-r[1])*W}%;width:${Math.max(0,r[1])*W}%;background:var(--warn);border-radius:3px"></i></div></td><td>${r[1]>=0?'+':''}${eur(r[1])}</td><td>${eur(r[2])}</td></tr>`).join('')}
      </tbody></table></div><p class="note-s">2040 vs 2026, Eesti kokku, 2026. aasta hindades. Iga rida lisab ühe teguri eelmistele. Variant arvestab praegust koolivõrgu poliitikat (${P.minSchool>0?'liitmise lävi '+P.minSchool+' õpilast':'koolivõrk ei muutu'}).</p>`;
    box.innerHTML = FC_DEC;
  };
  setTimeout(next, 30);
}
